from datetime import datetime, timedelta

FMT = "%Y-%m-%dT%H:%M:%SZ"

def read_since(source, watermark, lookback_hours):
    since = (datetime.strptime(watermark, FMT) - timedelta(hours=lookback_hours)).strftime(FMT)
    return [r for r in source if r[1] > since]

def load(source, lookback_hours):
    table, watermark = {}, "1970-01-01T00:00:00Z"
    for batch in source:
        rows = read_since(batch, watermark, lookback_hours)
        for r in rows:
            table[r[0]] = r
        if rows:
            watermark = max([watermark] + [r[1] for r in rows])
    return sorted(table)

source2 = [[(5, "2025-03-04T12:00:00Z")], [(5, "2025-03-04T12:00:00Z"), (6, "2025-03-04T10:00:00Z")]]
print(load(source2, 0))
print(load(source2, 3))
